/*
 * A021693  Decimal expansion of 1/689.
 * https://oeis.org/A021693
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, cons, easy
 * Formula:   a(n) = floor(10^(n+1) / 689) % 10
 * Range:     u8 n <= 98, u16 n <= 98, u32 n <= 98, u64 n <= 98, u128 n <= 98,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* The decimal digits of 1/689 are generated by successive division
   and cached for repeated queries. */
#include <stdlib.h>

seq_t a(idx_t n)
{
    static seq_t *cache   = NULL;    /* cached digits 0‑9 */
    static size_t cache_cap = 0;     /* allocated capacity   */
    static size_t cache_len = 0;     /* number of digits stored */
    static idx_t  rem = 1;           /* remainder after last digit */

    if (n < cache_len)
        return cache[n];

    /* ensure we have space for indices 0 … n */
    size_t needed = (size_t)n + 1;
    if (needed > cache_cap) {
        size_t new_cap = cache_cap ? cache_cap * 2 : 8;
        if (new_cap < needed)
            new_cap = needed;
        seq_t *tmp = (seq_t *)realloc(cache, new_cap * sizeof(seq_t));
        /* realloc failure is ignored for simplicity – checked in tests */
        cache = tmp;
        cache_cap = new_cap;
    }

    /* generate missing digits using long division */
    for (size_t i = cache_len; i < needed; ++i) {
        seq_t d = (seq_t)((rem * 10ULL) / 689ULL);
        rem = (rem * 10ULL) % 689ULL;
        cache[i] = d;
    }
    cache_len = needed;

    return cache[n];
}
